<script lang="ts">
	import type { PageData, ActionData } from './$types';
	let { data, form }: { data: PageData; form: ActionData } = $props();
	const open = $derived(data.tickets.filter((t) => t.status === 'open').length);
	const escalated = $derived(data.tickets.filter((t) => t.status === 'escalated').length);
	const resolved = $derived(data.tickets.filter((t) => t.status === 'resolved').length);
	const rated = $derived(data.tickets.filter((t) => t.rating));
	const averageRating = $derived(rated.length ? (rated.reduce((sum, t) => sum + (t.rating ?? 0), 0) / rated.length).toFixed(1) : '—');
	const categories = $derived(Object.entries(data.tickets.reduce((all, t) => { all[t.category] = (all[t.category] ?? 0) + 1; return all; }, {} as Record<string, number>)).sort((a, b) => b[1] - a[1]).slice(0, 4));
	let filter = $state('all');
	const filtered = $derived(filter === 'all' ? data.tickets : data.tickets.filter((t) => t.status === filter));
	const selected = $derived(data.detail?.ticket ?? null);
</script>

<svelte:head><title>Support operations · ZENRES</title><meta name="robots" content="noindex, nofollow, noarchive" /></svelte:head>

<div class="support-admin">
	<header class="top"><div><a href="/ops-vault" class="back">← Admin workspace</a><span class="eyebrow">ZENRES / SUPPORT OPERATIONS</span><h1>Every conversation,<br /><span>in focus.</span></h1><p>PGP-authenticated support queue. Customer records stay outside this workspace.</p></div><div class="top-actions"><span>PRIVATE · {data.canManage ? 'MANAGER' : 'ASSIGNED AGENT'}</span><a href="/ops-vault/support">Refresh ↻</a></div></header>
	{#if data.unavailable}<div class="unavailable" role="alert">The support service is unavailable or its database migration has not been applied. No customer records are shown.</div>{:else}
	<div class="stats"><article><span>OPEN</span><strong>{open}</strong><small>Awaiting team response</small></article><article><span>ESCALATED</span><strong>{escalated}</strong><small>Needs specialist review</small></article><article><span>RESOLVED</span><strong>{resolved}</strong><small>Closed conversations</small></article><article><span>SATISFACTION</span><strong>{averageRating}</strong><small>{rated.length ? `${rated.length} rated tickets / 5` : 'No ratings yet'}</small></article></div>
	<div class="main-grid"><section class="queue"><div class="panel-head"><div><span class="eyebrow">01 / TICKET QUEUE</span><h2>Requests</h2></div><select aria-label="Filter tickets by status" bind:value={filter}><option value="all">All statuses</option><option value="open">Open</option><option value="pending">Pending</option><option value="escalated">Escalated</option><option value="resolved">Resolved</option></select></div><div class="queue-list">{#each filtered as ticket (ticket.id)}<a class:active={selected?.id === ticket.id} href="/ops-vault/support?id={ticket.id}"><span class="line"><small>ZEN-{ticket.number} · {ticket.category}</small><em class:urgent={ticket.priority === 'urgent' || ticket.priority === 'high'}>{ticket.priority}</em></span><strong>{ticket.subject}</strong><span class="line"><small>{ticket.plan} · {ticket.status}</small><small>{new Date(ticket.created_at).toLocaleDateString('en-IN')}</small></span></a>{/each}{#if filtered.length === 0}<p class="empty">No tickets in this view.</p>{/if}</div></section>
	<section class="detail">{#if selected}<div class="panel-head"><div><span class="eyebrow">02 / ZEN-{selected.number}</span><h2>{selected.subject}</h2></div><span class="status">{selected.status}</span></div><div class="metadata"><div><span>REQUESTER</span><strong>{selected.requester}</strong></div><div><span>PLAN</span><strong>{selected.plan}</strong></div><div><span>CATEGORY</span><strong>{selected.category}</strong></div><div><span>ASSIGNED AGENT</span><strong>{selected.assigned_to || 'Unassigned'}</strong></div><div><span>FIRST RESPONSE</span><strong>{selected.first_response_at ? new Date(selected.first_response_at).toLocaleString() : 'Pending'}</strong></div><div><span>RESOLUTION</span><strong>{selected.resolved_at ? new Date(selected.resolved_at).toLocaleString() : 'Pending'}</strong></div>{#if selected.callback_at}<div><span>REQUESTED CALLBACK</span><strong>{new Date(selected.callback_at).toLocaleString()}</strong></div>{/if}</div><div class="privacy">Financial records are not available in this view. Request separate explicit authorisation before any future access.</div><h3>Conversation history</h3><div class="messages">{#each data.detail?.messages ?? [] as message (message.id)}<article class:internal={message.internal}><span>{message.author === 'support' ? 'Support agent' : 'Customer'}{message.internal ? ' · internal note' : ''} · {new Date(message.created_at).toLocaleString()}</span><p>{message.body}</p></article>{/each}</div><form method="POST" action="?/update"><input type="hidden" name="id" value={selected.id} /><div class="controls"><label>Status<select name="status"><option value="">Keep current</option>{#each ['open','pending','escalated','resolved'] as state}<option value={state}>{state}</option>{/each}</select></label>{#if data.canManage}<label>Priority<select name="priority"><option value="">Keep current</option>{#each ['low','normal','high','urgent'] as priority}<option value={priority}>{priority}</option>{/each}</select></label><label>Assign to<select name="assignee_id"><option value="">Keep current</option>{#each data.agents as agent (agent.id)}<option value={agent.id}>{agent.handle} · {agent.role}</option>{/each}</select></label>{/if}</div><label>Reply or note<textarea name="message" rows="4" maxlength="4000" placeholder="Write a reply. Leave blank to change status or assignment."></textarea></label><label class="check"><input type="checkbox" name="internal_note" /> Internal note, hidden from customer</label><h3>Record support work</h3><div class="controls"><label>Minutes<input name="work_minutes" type="number" min="1" max="480" placeholder="Optional" /></label>{#if data.canManage}<label>Actual cost<input name="work_cost" inputmode="decimal" placeholder="Optional" /></label><label>Currency<select name="work_currency"><option value="">No cost recorded</option><option value="USD">USD</option><option value="INR">INR</option><option value="EUR">EUR</option></select></label>{/if}</div><label>Work note<input name="work_note" maxlength="500" placeholder="Optional internal description" /></label><button type="submit">Save update <span>↗</span></button>{#if form?.message}<p class="message-status" role="status">{form.message}</p>{/if}</form>{:else}<div class="detail-empty"><span>◌</span><h2>Select a ticket</h2><p>Open a request to read its history and update the team workflow.</p></div>{/if}</section></div>
	<div class="secondary"><section><span class="eyebrow">03 / RECURRING ISSUES</span><h2>Topics in this queue</h2>{#each categories as [category, count]}<div class="topic"><span>{category}</span><strong>{count}</strong></div>{/each}{#if categories.length === 0}<p>No ticket topics yet.</p>{/if}{#if data.canManage}<h2>Recorded cost by customer</h2>{#each data.costs as entry}<div class="topic"><span>{entry.customer} · {entry.minutes} min</span><strong>{entry.currency} {entry.amount}</strong></div>{/each}{#if data.costs.length === 0}<p class="small">No actual costs recorded yet. Add minutes and an actual cost on a ticket; no staffing rate is assumed.</p>{/if}{/if}</section>{#if data.canManage}<section><span class="eyebrow">04 / SERVICE COMMUNICATIONS</span><h2>Publish a status notice</h2><form method="POST" action="?/announcement"><label>Title<input name="title" minlength="5" maxlength="160" required placeholder="Planned maintenance" /></label><label>State<select name="state"><option value="maintenance">Maintenance</option><option value="incident">Incident</option><option value="resolved">Resolved</option></select></label><label>Public details<textarea name="body" minlength="5" maxlength="2000" rows="3" required placeholder="What is affected and when to check back"></textarea></label><button type="submit">Publish notice <span>↗</span></button></form><p class="small">Published notices appear on the public support centre. Confirm the details before publishing.</p></section>{/if}</div>
	{/if}
</div>

