 13px; background: #edf4f9; padding: 14px; }.messages article.internal { background: #f8f2e7; }.messages span { color: #8192a3; font-size: 10px; }.messages p { margin-top: 7px; color: #4b5f71; font-size: 13px; line-height: 1.55; white-space: pre-wrap; }.detail form { border-top: 1px solid #e5edf3; padding-top: 18px; margin-top: 20px; }.controls { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }form label { display: flex; flex-direction: column; gap: 7px; color: #71869a; font-size: 11px; margin-bottom: 13px; }form select,form input:not([type=checkbox]),form textarea { border: 1px solid #dce6ee; border-radius: 11px; padding: 11px; color: #415971; width: 100%; background: #fbfdff; }form textarea { resize: vertical; }form .check { flex-direction: row; align-items: center; }form button { display: inline-flex; gap: 22px; border-radius: 100px; background: #b6d8ee; color: #39516a; padding: 12px 18px; font-size: 12px; font-weight: 650; transition: transform .25s; }form button:hover { transform: translateY(-2px); }.message-status { font-size: 12px; color: #5e7a94; margin-top: 12px; }.detail-empty { display: grid; place-content: center; text-align: center; min-height: 450px; color: #8999aa; }.detail-empty span { font-size: 70px; }.detail-empty h2 { color: #52687b; font-size: 26px; }.detail-empty p { margin-top: 9px; }
